namespace Inventory;

/// <summary>
/// Applies stock adjustments, makes reorder decisions, allocates zones and
/// places supplier orders.
/// </summary>
public sealed class StockController
{
    private readonly StockOperations _operations;

    public StockController(ISupplier supplier)
    {
        _operations = new StockOperations(supplier);
    }

    public int AdjustStock(StockItem item, int delta) =>
        _operations.Adjustments.AdjustStock(item, delta);

    public int Available(StockItem item) =>
        _operations.Adjustments.Available(item);

    public int MovementCount => _operations.Adjustments.MovementCount;

    public bool NeedsReorder(StockItem item) =>
        _operations.Reordering.NeedsReorder(item);

    public int ReorderQuantity(StockItem item) =>
        _operations.Reordering.ReorderQuantity(item);

    public int ResolveThreshold(string sku) =>
        _operations.Reordering.ResolveThreshold(sku);

    public string AllocateToZone(StockItem item, Warehouse warehouse) =>
        _operations.ZoneAllocation.AllocateToZone(item, warehouse);

    public int ZoneSpare(Warehouse warehouse) =>
        _operations.ZoneAllocation.ZoneSpare(warehouse);

    public bool PlaceReorder(StockItem item) =>
        _operations.SupplierOrdering.PlaceReorder(item);

    public bool ConfirmDelivery(StockItem item, int delivered) =>
        _operations.SupplierOrdering.ConfirmDelivery(item, delivered);

    public string Classify(StockItem item) =>
        _operations.Analysis.Classify(item);

    public IReadOnlyList<string> AuditStock(StockItem item, Warehouse warehouse) =>
        _operations.Analysis.AuditStock(item, warehouse);

    public int ForecastDepletion(StockItem item, int dailyDemand) =>
        _operations.Analysis.ForecastDepletion(item, dailyDemand);
}

internal sealed class StockOperations
{
    public StockOperations(ISupplier supplier)
    {
        Adjustments = new StockAdjustments();
        Reordering = new StockReordering();
        ZoneAllocation = new StockZoneAllocation();
        SupplierOrdering = new StockSupplierOrdering(supplier, Reordering);
        Analysis = new StockAnalysis(Reordering, ZoneAllocation);
    }

    public StockAdjustments Adjustments { get; }

    public StockReordering Reordering { get; }

    public StockZoneAllocation ZoneAllocation { get; }

    public StockSupplierOrdering SupplierOrdering { get; }

    public StockAnalysis Analysis { get; }
}

internal sealed class StockAdjustments
{
    private readonly List<string> _movements = new();

    public int AdjustStock(StockItem item, int delta)
    {
        if (delta == 0)
            return item.OnHand;
        if (delta < 0 && item.OnHand + delta < 0)
            return item.OnHand;

        item.OnHand += delta;
        if (delta > 0)
            _movements.Add($"IN {item.Sku} {delta}");
        else
            _movements.Add($"OUT {item.Sku} {-delta}");

        if (item.OnHand < item.Reserved)
            _movements.Add($"WARN {item.Sku} oversold");

        return item.OnHand;
    }

    public int Available(StockItem item)
    {
        int free = item.OnHand - item.Reserved;
        if (free < 0)
            return 0;
        return free;
    }

    public int MovementCount => _movements.Count;
}

internal sealed class StockReordering
{
    private readonly Dictionary<string, int> _reorderThresholds = new(StringComparer.Ordinal);
    private readonly int _defaultReorder = 20;

    public bool NeedsReorder(StockItem item)
    {
        if (item.Sku.Length == 0)
            return false;

        int available = item.OnHand - item.Reserved;
        var threshold = ResolveThreshold(item.Sku);
        if (item.ReorderPoint > 0)
            return available <= item.ReorderPoint;
        return available <= threshold;
    }

    public int ReorderQuantity(StockItem item)
    {
        if (!NeedsReorder(item))
            return 0;

        int available = item.OnHand - item.Reserved;
        int target = item.ReorderPoint > 0 ? item.ReorderPoint * 2 : _defaultReorder * 2;
        int qty = target - available;
        if (qty < 0)
            qty = 0;
        else if (qty < 5)
            qty = 5;
        return qty;
    }

    public int ResolveThreshold(string sku)
    {
        if (string.IsNullOrEmpty(sku))
            return _defaultReorder;
        if (_reorderThresholds.TryGetValue(sku, out var threshold))
            return threshold;
        return _defaultReorder;
    }
}

internal sealed class StockZoneAllocation
{
    private readonly Dictionary<string, int> _zoneUsage = new(StringComparer.Ordinal);

    public string AllocateToZone(StockItem item, Warehouse warehouse)
    {
        if (warehouse.Zones.Count == 0)
            return "no zones";

        int need = item.OnHand - item.Reserved;
        if (need <= 0)
            return "nothing to place";

        foreach (var zone in warehouse.Zones)
        {
            var used = GetUsage(zone.Name);
            int spare = zone.Capacity - used;
            if (spare <= 0)
                continue;

            int place = need > spare ? spare : need;
            _zoneUsage[zone.Name] = used + place;
            need -= place;
            if (need <= 0)
                return $"placed in {zone.Name}";
        }

        return "overflow";
    }

    public int ZoneSpare(Warehouse warehouse)
    {
        int spare = 0;
        foreach (var zone in warehouse.Zones)
        {
            var used = GetUsage(zone.Name);
            if (zone.Capacity > used)
                spare += zone.Capacity - used;
        }
        return spare;
    }

    public void AppendAuditFindings(Warehouse warehouse, List<string> findings)
    {
        foreach (var zone in warehouse.Zones)
        {
            var used = GetUsage(zone.Name);
            if (used > zone.Capacity)
                findings.Add($"{zone.Name}:over-capacity");
            else if (used < 0)
                findings.Add($"{zone.Name}:negative-usage");
        }
    }

    private int GetUsage(string zoneName) =>
        _zoneUsage.TryGetValue(zoneName, out var usage) ? usage : 0;
}

internal sealed class StockSupplierOrdering
{
    private readonly ISupplier _supplier;
    private readonly StockReordering _reordering;
    private readonly Dictionary<string, int> _pending = new(StringComparer.Ordinal);

    public StockSupplierOrdering(ISupplier supplier, StockReordering reordering)
    {
        _supplier = supplier;
        _reordering = reordering;
    }

    public bool PlaceReorder(StockItem item)
    {
        var qty = _reordering.ReorderQuantity(item);
        if (qty <= 0)
            return false;
        if (_pending.TryGetValue(item.Sku, out var existing) && existing >= qty)
            return false;

        var accepted = _supplier.PlaceOrder(item.Sku, qty);
        if (accepted)
            _pending[item.Sku] = qty;
        return accepted;
    }

    public bool ConfirmDelivery(StockItem item, int delivered)
    {
        if (delivered <= 0)
            return false;
        if (!_pending.TryGetValue(item.Sku, out var qty))
            return false;

        item.OnHand += delivered;
        if (delivered >= qty)
            _pending.Remove(item.Sku);
        else
            _pending[item.Sku] = qty - delivered;
        return true;
    }
}

internal sealed class StockAnalysis
{
    private readonly StockReordering _reordering;
    private readonly StockZoneAllocation _zoneAllocation;

    public StockAnalysis(
        StockReordering reordering,
        StockZoneAllocation zoneAllocation)
    {
        _reordering = reordering;
        _zoneAllocation = zoneAllocation;
    }

    public string Classify(StockItem item)
    {
        int available = item.OnHand - item.Reserved;
        if (available < 0)
            return "oversold";
        if (available == 0)
            return "out";
        if (item.ReorderPoint > 0 && available <= item.ReorderPoint)
            return "low";
        else if (available > item.ReorderPoint * 5)
            return "excess";
        return "ok";
    }

    public IReadOnlyList<string> AuditStock(StockItem item, Warehouse warehouse)
    {
        var findings = new List<string>();
        if (item.OnHand < 0)
            findings.Add($"{item.Sku}:negative-onhand");
        if (item.Reserved < 0)
            findings.Add($"{item.Sku}:negative-reserve");
        if (item.OnHand < item.Reserved)
            findings.Add($"{item.Sku}:oversold");

        _zoneAllocation.AppendAuditFindings(warehouse, findings);

        if (findings.Count == 0)
            findings.Add("clean");
        return findings;
    }

    public int ForecastDepletion(StockItem item, int dailyDemand)
    {
        if (dailyDemand <= 0)
            return -1;

        int available = item.OnHand - item.Reserved;
        if (available <= 0)
            return 0;

        int days = available / dailyDemand;
        if (item.ReorderPoint > 0 && available <= item.ReorderPoint)
            return 0;
        if (days > 365)
            return 365;

        var threshold = _reordering.ResolveThreshold(item.Sku);
        if (threshold > 0 && available <= threshold)
            return 1;
        else if (days < 7)
            return days;
        return days;
    }
}
